package gitobj_test

import (
	"bytes"
	"os"
	"strings"
	"testing"

	"github.com/L0nelyG0d/micro-git/backend/gitobj"
)

// Fixtures in testdata/ were generated by testdata/gen.sh with real git:
//   git init; git add -A; git write-tree
//   git commit-tree <tree> [-p <parent>]  (GIT_*_DATE="1700000000 +0000")
//   git cat-file tree|commit <oid> > *.bin; git hash-object <file>
// oids.txt holds git's own answers.

func oids(t *testing.T) map[string]string {
	t.Helper()
	data, err := os.ReadFile("testdata/oids.txt")
	if err != nil {
		t.Fatal(err)
	}
	m := map[string]string{}
	for _, l := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		k, v, _ := strings.Cut(l, " ")
		m[k] = v
	}
	return m
}

func read(t *testing.T, name string) []byte {
	t.Helper()
	b, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func TestBlobHash(t *testing.T) {
	t.Parallel()
	tests := []struct{ name, content, want string }{
		{"empty", "", "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391"},
		{"test content", "test content\n", "d670460b4b4aece5915caf5c68d12f560a9fe3e4"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if got := gitobj.HashBlob([]byte(tc.content)); got != tc.want {
				t.Errorf("got %s, want %s", got, tc.want)
			}
		})
	}
}

func TestHashFormat(t *testing.T) {
	t.Parallel()
	got := gitobj.Hash(gitobj.TypeBlob, []byte("héllo")) // multibyte: len is bytes
	if !gitobj.ValidOID(got) {
		t.Errorf("not 40 lowercase hex: %q", got)
	}
	if got == gitobj.Hash(gitobj.TypeBlob, []byte("hello")) {
		t.Error("different bodies hashed equal")
	}
}

func fixtureTree(t *testing.T) []gitobj.TreeEntry {
	o := oids(t)
	f, d := gitobj.ModeFile, gitobj.ModeDir
	return []gitobj.TreeEntry{ // deliberately unsorted
		{Mode: d, Name: "sub", OID: o["sub"]},
		{Mode: d, Name: "foo", OID: o["foo"]},
		{Mode: f, Name: "foo.txt", OID: o["foo.txt"]},
		{Mode: f, Name: "a.txt", OID: o["a.txt"]},
		{Mode: f, Name: "foo-bar", OID: o["foo-bar"]},
	}
}

func TestTreeMatchesGit(t *testing.T) {
	t.Parallel()
	o := oids(t)
	body, err := gitobj.SerializeTree(fixtureTree(t))
	if err != nil {
		t.Fatal(err)
	}
	if want := read(t, "tree.bin"); !bytes.Equal(body, want) {
		t.Errorf("tree body differs from git:\n got %q\nwant %q", body, want)
	}
	if got := gitobj.Hash(gitobj.TypeTree, body); got != o["tree"] {
		t.Errorf("got %s, want %s", got, o["tree"])
	}
}

func TestTreeNestedMatchesGit(t *testing.T) {
	t.Parallel()
	o := oids(t)
	deep, _ := gitobj.SerializeTree([]gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "d.txt", OID: o["sub/deep/d.txt"]}})
	if got := gitobj.Hash(gitobj.TypeTree, deep); got != o["sub/deep"] {
		t.Errorf("sub/deep: got %s, want %s", got, o["sub/deep"])
	}
	sub, _ := gitobj.SerializeTree([]gitobj.TreeEntry{{Mode: gitobj.ModeDir, Name: "deep", OID: o["sub/deep"]}})
	if got := gitobj.Hash(gitobj.TypeTree, sub); got != o["sub"] {
		t.Errorf("sub: got %s, want %s", got, o["sub"])
	}
}

func TestTreeSortOrder(t *testing.T) {
	t.Parallel()
	entries := fixtureTree(t)
	gitobj.SortTreeEntries(entries)
	var names []string
	for _, e := range entries {
		names = append(names, e.Name)
	}
	// Plain name order would put "foo" before "foo-bar" and "foo.txt".
	want := "a.txt foo-bar foo.txt foo sub"
	if got := strings.Join(names, " "); got != want {
		t.Errorf("got %q, want %q", got, want)
	}
}

func TestTreeModes(t *testing.T) {
	t.Parallel()
	body, _ := gitobj.SerializeTree(fixtureTree(t))
	if !bytes.Contains(body, []byte("40000 foo\x00")) || bytes.Contains(body, []byte("040000")) {
		t.Error("directory mode must be 40000")
	}
	if !bytes.Contains(body, []byte("100644 a.txt\x00")) {
		t.Error("file mode must be 100644")
	}
}

func TestSerializeTreeErrors(t *testing.T) {
	t.Parallel()
	oid := strings.Repeat("a", 40)
	tests := []struct {
		name string
		in   []gitobj.TreeEntry
	}{
		{"bad mode", []gitobj.TreeEntry{{Mode: "100755", Name: "x", OID: oid}}},
		{"slash in name", []gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "a/b", OID: oid}}},
		{"empty name", []gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "", OID: oid}}},
		{"short oid", []gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "x", OID: "abc"}}},
		{"uppercase oid", []gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "x", OID: strings.Repeat("A", 40)}}},
		{"duplicate", []gitobj.TreeEntry{{Mode: gitobj.ModeFile, Name: "x", OID: oid}, {Mode: gitobj.ModeDir, Name: "x", OID: oid}}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := gitobj.SerializeTree(tc.in); err == nil {
				t.Error("expected error")
			}
		})
	}
}

func TestEmptyTree(t *testing.T) {
	t.Parallel()
	body, err := gitobj.SerializeTree(nil)
	if err != nil {
		t.Fatal(err)
	}
	if got := gitobj.Hash(gitobj.TypeTree, body); got != "4b825dc642cb6eb9a060e54bf8d69288fbee4904" {
		t.Errorf("got %s", got)
	}
	got, err := gitobj.ParseTree(body)
	if err != nil || len(got) != 0 {
		t.Errorf("got %v, %v", got, err)
	}
}

func TestTreeRoundTrip(t *testing.T) {
	t.Parallel()
	entries := fixtureTree(t)
	body, _ := gitobj.SerializeTree(entries)
	got, err := gitobj.ParseTree(body)
	if err != nil {
		t.Fatal(err)
	}
	gitobj.SortTreeEntries(entries)
	if len(got) != len(entries) {
		t.Fatalf("got %d entries, want %d", len(got), len(entries))
	}
	for i := range got {
		if got[i] != entries[i] {
			t.Errorf("entry %d: got %v, want %v", i, got[i], entries[i])
		}
	}
}

func alice(unix int64) gitobj.Signature {
	return gitobj.Signature{Name: "alice", Email: "alice@micro-git.local", Unix: unix}
}

func TestCommitMatchesGit(t *testing.T) {
	t.Parallel()
	o := oids(t)
	tests := []struct {
		name, file, wantOID string
		c                   gitobj.Commit
	}{
		{"zero parents", "commit0.bin", o["commit0"], gitobj.Commit{
			Tree: o["tree"], Author: alice(1700000000), Committer: alice(1700000000), Message: "first commit"}},
		{"one parent", "commit1.bin", o["commit1"], gitobj.Commit{
			Tree: o["tree1"], Parents: []string{o["commit0"]},
			Author: alice(1700000100), Committer: alice(1700000100), Message: "second commit"}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			body, err := gitobj.SerializeCommit(tc.c)
			if err != nil {
				t.Fatal(err)
			}
			if want := read(t, tc.file); !bytes.Equal(body, want) {
				t.Errorf("body differs from git:\n got %q\nwant %q", body, want)
			}
			if got := gitobj.Hash(gitobj.TypeCommit, body); got != tc.wantOID {
				t.Errorf("got %s, want %s", got, tc.wantOID)
			}
		})
	}
}

func TestCommitMultipleParentsInOrder(t *testing.T) {
	t.Parallel()
	p1, p2, p3 := strings.Repeat("3", 40), strings.Repeat("1", 40), strings.Repeat("2", 40)
	c := gitobj.Commit{Tree: strings.Repeat("a", 40), Parents: []string{p1, p2, p3},
		Author: alice(1), Committer: alice(1), Message: "m"}
	body, err := gitobj.SerializeCommit(c)
	if err != nil {
		t.Fatal(err)
	}
	want := "parent " + p1 + "\nparent " + p2 + "\nparent " + p3 + "\nauthor"
	if !strings.Contains(string(body), want) {
		t.Errorf("parents not in order:\n%s", body)
	}
	got, err := gitobj.ParseCommit(body)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Join(got.Parents, ",") != strings.Join(c.Parents, ",") {
		t.Errorf("got %v", got.Parents)
	}
}

func TestCommitMessageNormalized(t *testing.T) {
	t.Parallel()
	c := gitobj.Commit{Tree: strings.Repeat("a", 40), Author: alice(1), Committer: alice(1), Message: "  hello\n\n\n"}
	body, _ := gitobj.SerializeCommit(c)
	if !strings.HasSuffix(string(body), "\n\nhello\n") {
		t.Errorf("got %q", body)
	}
}

func TestCommitRoundTrip(t *testing.T) {
	t.Parallel()
	o := oids(t)
	for _, f := range []string{"commit0.bin", "commit1.bin"} {
		t.Run(f, func(t *testing.T) {
			raw := read(t, f)
			c, err := gitobj.ParseCommit(raw)
			if err != nil {
				t.Fatal(err)
			}
			again, err := gitobj.SerializeCommit(c)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Equal(again, raw) {
				t.Errorf("round trip differs:\n got %q\nwant %q", again, raw)
			}
		})
	}
	c, _ := gitobj.ParseCommit(read(t, "commit1.bin"))
	if c.Author.Name != "alice" || c.Author.Email != "alice@micro-git.local" || c.Author.Unix != 1700000100 ||
		c.Parents[0] != o["commit0"] || c.Message != "second commit\n" {
		t.Errorf("unexpected parse: %+v", c)
	}
}

func TestBlobRoundTrip(t *testing.T) {
	t.Parallel()
	// A blob body is the content itself; hashing is deterministic over it.
	in := []byte("x\x00y\n")
	if gitobj.HashBlob(in) != gitobj.HashBlob(append([]byte(nil), in...)) {
		t.Error("blob hash not stable")
	}
}

func TestParseTreeMalformed(t *testing.T) {
	t.Parallel()
	oid := strings.Repeat("\x01", 20)
	tests := []struct{ name, in string }{
		{"no space", "100644"},
		{"missing NUL", "100644 name"},
		{"truncated oid", "100644 name\x00" + oid[:10]},
		{"oid one byte short", "100644 name\x00" + oid[:19]},
		{"bad mode", "abc name\x00" + oid},
		{"empty name", "100644 \x00" + oid},
		{"trailing garbage", "100644 a\x00" + oid + "40000"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := gitobj.ParseTree([]byte(tc.in)); err == nil {
				t.Error("expected error")
			}
		})
	}
}

func TestParseCommitMalformed(t *testing.T) {
	t.Parallel()
	oid := strings.Repeat("a", 40)
	sig := "alice <alice@micro-git.local> 1 +0000"
	tests := []struct{ name, in string }{
		{"empty", ""},
		{"no tree", "author " + sig + "\ncommitter " + sig + "\n\nmsg\n"},
		{"bad tree oid", "tree abc\nauthor " + sig + "\ncommitter " + sig + "\n\nmsg\n"},
		{"bad parent", "tree " + oid + "\nparent zz\nauthor " + sig + "\ncommitter " + sig + "\n\nmsg\n"},
		{"no blank line", "tree " + oid + "\nauthor " + sig},
		{"no author", "tree " + oid + "\ncommitter " + sig + "\n\nmsg\n"},
		{"bad signature", "tree " + oid + "\nauthor nobody\ncommitter " + sig + "\n\nmsg\n"},
		{"bad time", "tree " + oid + "\nauthor alice <a@b> x +0000\ncommitter " + sig + "\n\nmsg\n"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := gitobj.ParseCommit([]byte(tc.in)); err == nil {
				t.Error("expected error")
			}
		})
	}
}

func TestSerializeCommitInvalidOIDs(t *testing.T) {
	t.Parallel()
	ok := strings.Repeat("a", 40)
	if _, err := gitobj.SerializeCommit(gitobj.Commit{Tree: "short"}); err == nil {
		t.Error("expected error for bad tree")
	}
	if _, err := gitobj.SerializeCommit(gitobj.Commit{Tree: ok, Parents: []string{"x"}}); err == nil {
		t.Error("expected error for bad parent")
	}
}
